      "กาหนดการออกแบบส่วนต่อประสานที่ดี",
      "ออกแบบและประเมินผลระบบเชิงโต้ตอบ",
      "ดาเนินโครงงานประยุกต์ด้านการปฏิสัมพันธ์ระหว่างมนุษย์และคอมพิวเตอร์ รวมทั้งสามารถนาเสนอโครงงาน ทั้งในรูปแบบปากเปล่าและการเขียนได้อย่างมีประสิทธิภาพ",
