      "Determine the good interface design.",
      "Design and evaluate interactive systems.",
      "Work as a team for carrying out a project, as well as be able to present their project effectively in both oral and written forms.",
      "Demonstrate professional ethics, have discipline, punctuality, as well as self and social responsibility."
