      "พัฒนาโครงงานโดยประยุกต์ใช้ฐานความรู้ออนโทโลยี และโปรแกรมประยุกต์สาหรับสืบค้นข้อมูลเชิง ความหมาย โดยการประยุกต์แนวคิดวิศวกรรมออนโทโลยีได้ รวมทั้งสามารถเขียนเอกสารรายงาน และ นาเสนอโครงงานได้อย่างมีประสิทธิภาพ",
