    "desc_TH": "แนะนำระบบสารสนเทศและโมเดลธุรกิจ ระบบประมวลผลรายการธุรกิจ ระบบสารสนเทศการจัดการและธุรกิจอัจฉริยะ ระบบสนับสนุนการตัดสินใจ ระบบสารสนเทศผู้บริหาร และระบบผู้เชี่ยวชาญและปัญญาประดิษฐ์",
    "desc_EN": "Introduction to information system and business model, business transaction processing system, management information system and business intelligence, decision support system, executive information system, and expert system and artificial intelligence.",
