    "name_EN": "Computer Network Design and Management",
    "credits": "3(2-2-5)",
    "desc_TH": "ระบบเครือข่ายและอินเทอร์เน็ต แนวคิดการจัดสรรเส้นทางและการส่งต่อแพ็กเกต แลนและสวิตชิง การจัดสรรเส้นทางแบบคงที่ การจัดสรรเส้นทางแบบเปลี่ยนแปลงได้ และเน็ตเวิร์คแอดเดรสทรานสเลชัน และการจัดการเครือข่าย",
