    "desc_TH": "กระบวนวิชานี้เป็นการศึกษา หรือค้นคว้า ในหัวข้อวิทยาการคอมพิวเตอร์ ซึ่งนักศึกษาสามารถนำเอาหัวข้อนี้ไปศึกษาเพิ่มเติมในกระบวนวิชา 204499 การค้นคว้าอิสระ 2 ต่อได้ โดยนักศึกษาจะเป็นผู้ดำเนินการภายใต้การดูแลของอาจารย์ที่ปรึกษา และจะต้องส่งรายงานผลการค้นคว้า และนำเสนอคณะกรรมการ โดยรายงานที่ประเมินนี้จะผ่านการประเมินเป็นลำดับขั้น S หรือ U",
    "desc_EN": "This course is designed for the students to study and conduct a research project in a topic of computer science, which the students may carry on into 204499 Independent Study II. The students must be under the supervision of the advisor. In order to complete this course, the students must submit a report and present it to the committee. Grading will be given on satisfactory or unsatisfactory basis.",
    "CLOs_TH": [
      "นักศึกษาสามารถดาเนินโครงงานค้นคว้าในสาขาวิทยาการคอมพิวเตอร์ในประเด็นที่สนใจ",
      "นักศึกษาสามารถเขียนรายงานผลการค้นคว้า รวมทั้งสามารถนาเสนอในรูปแบบปากเปล่าได้อย่างมี ประสิทธิภาพ",
      "นักศึกษาแสดงพฤติกรรมความเป็นผู้มีจรรยาบรรณทางวิชาชีพ มีวินัย ตรงต่อเวลา รวมทั้งมีความรับผิดชอบ ต่อตนเองและสังคม"
    ],
    "CLOs_EN": [
      "Students are able to conduct a research project in an area of computer science based on their interested topic.",
      "Students are able to write their research report, as well as able to present their research effectively in an oral form.",
      "Students demonstrate their behavior in professional ethics, discipline, punctuality, as well as being responsible for themselves and society."
    ],
