      "อธิบายข้อคำนึงทางจริยธรรมและกฎหมายที่เกี่ยวกับปัญญาประดิษฐ์ได้",
      "เขียนโปรแกรมสำหรับการแก้ปัญหาขนาดเล็กโดยประยุกต์ใช้แนวคิดของปัญญาประดิษฐ์ได้",
