      "นักศึกษาสามารถสืบค้นข้อมูลเกี่ยวกับความก้าวหน้าของเทคโนโลยีคอมพิวเตอร์ที่เกี่ยวข้องกับการประยุกต์ เครื่องมือและเทคนิคการพัฒนาระบบงานบนเว็บในปัจจุบัน รวมทั้งสามารถเขียนรายงานสรุปจากประเด็นที่ ศึกษาได้",
      "นักศึกษาสามารถทางานเป็นทีมเพื่อดาเนินโครงงานขนาดเล็กโดยประยุกต์รูปแบบสถาปัตยกรรมเว็บที่ เหมาะสม รวมทั้งสามารถนาเสนอแนวคิดของตนในรูปแบบปากเปล่าได้",
