    "desc_EN": "Introduction to numerical computation, linear system of equations and program implementation, interpolations and program implementation, numerical quadrature and program implementation, numerical differentiation and program implementation, linear least squares data fitting and program implementation, solution of nonlinear equations and program implementation.",
