      "นักศึกษาสามารถวิเคราะห์โมเดลธุรกิจ เช่น การจัดการห่วงโซ่อุปทาน การจัดการลูกค้าสัมพันธ์ ความมั่นคง ของระบบสารสนเทศ และประเด็นจริยธรรมและสังคมในระบบสารสนเทศ",
