      "นักศึกษาสามารถวิเคราะห์โครงสร้างของเครือข่าย เพื่อให้ทราบองค์ประกอบและลักษณะการทางานใน เบื้องต้น และสามารถแก้ไขปัญหาการทางานที่ผิดพลาดของเครือข่าย โดยตรวจสอบและแก้ไขการตั้งค่า อุปกรณ์เครือข่าย",
      "นักศึกษาสามารถประยุกต์ใช้แนวคิดเกี่ยวกับการจัดสรรเส้นทาง และสวิตชิง สาหรับการออกแบบและการตั้ง ค่าพื้นฐานให้กับอุปกรณ์เครือข่าย เพื่อให้ระบบเครือข่ายสามารถทางานได้ตามข้อกาหนด",
