      "apply computer science knowledge integrated with other related knowledge to produce works assigned by an organization.",
      "write their work report, as well as able to present their research effectively in an oral form.",
      "demonstrate their behavior in professional ethics, discipline, punctuality, as well as being responsible for themselves and society.",
      "Students are able to analyze and propose solution to problems assigned by an organization using computer science knowledge integrated with other related knowledge.",
      "Students are able to apply computer science knowledge integrated with other related knowledge to produce works assigned by an organization.",
